#ifndef ZOVUTILS_LS_BACKEND_H
#define ZOVUTILS_LS_BACKEND_H
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <dirent.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pwd.h>
#include <grp.h>
#include <time.h>
#include <limits.h>
#if defined(__linux__)
#include <sys/xattr.h>
#endif
#ifndef PATH_MAX
#define PATH_MAX 4096
#endif
static inline char*zov_lsdup(const char*s){size_t n=strlen(s);char*p=(char*)malloc(n+1);if(p)memcpy(p,s,n+1);return p;}
typedef struct{char*name;struct stat st;int valid;}zov_lsentry;
static int zov_ls_sort_mode;
static int zov_ls_reverse;
static inline int zov_lscmp(const void*a,const void*b){const zov_lsentry*x=(const zov_lsentry*)a,*y=(const zov_lsentry*)b;int r=0;if(zov_ls_sort_mode==1&&x->st.st_size!=y->st.st_size)r=x->st.st_size>y->st.st_size?-1:1;else if(zov_ls_sort_mode==2&&x->st.st_mtime!=y->st.st_mtime)r=x->st.st_mtime>y->st.st_mtime?-1:1;else r=strcmp(x->name,y->name);return zov_ls_reverse?-r:r;}
static inline char*zov_lspath(const char*dir,const char*name){size_t a=strlen(dir),b=strlen(name);char*p=(char*)malloc(a+b+2);if(!p)return NULL;memcpy(p,dir,a);size_t n=a;if(n&&p[n-1]!='/')p[n++]='/';memcpy(p+n,name,b+1);return p;}
static inline void zov_ls_mode(mode_t m,char out[11]){out[0]=S_ISDIR(m)?'d':S_ISLNK(m)?'l':S_ISCHR(m)?'c':S_ISBLK(m)?'b':S_ISFIFO(m)?'p':S_ISSOCK(m)?'s':'-';const mode_t bits[9]={S_IRUSR,S_IWUSR,S_IXUSR,S_IRGRP,S_IWGRP,S_IXGRP,S_IROTH,S_IWOTH,S_IXOTH};const char chars[9]={'r','w','x','r','w','x','r','w','x'};for(int i=0;i<9;i++)out[i+1]=(m&bits[i])?chars[i]:'-';if(m&S_ISUID)out[3]=(m&S_IXUSR)?'s':'S';if(m&S_ISGID)out[6]=(m&S_IXGRP)?'s':'S';if(m&S_ISVTX)out[9]=(m&S_IXOTH)?'t':'T';out[10]=0;}
static inline int zov_ls_digits(long long n){int d=1;while(n>=10){n/=10;d++;}return d;}
static inline void zov_ls_long(const char*name,const struct stat*st,const char*full,int sw){char mode[11],owner[128],group[128],date[64];zov_ls_mode(st->st_mode,mode);struct passwd*p=getpwuid(st->st_uid);if(p)snprintf(owner,sizeof owner,"%s",p->pw_name);else snprintf(owner,sizeof owner,"%lu",(unsigned long)st->st_uid);struct group*g=getgrgid(st->st_gid);if(g)snprintf(group,sizeof group,"%s",g->gr_name);else snprintf(group,sizeof group,"%lu",(unsigned long)st->st_gid);time_t now=time(NULL);struct tm t;localtime_r(&st->st_mtime,&t);if(st->st_mtime>now+15552000||st->st_mtime<now-15552000)strftime(date,sizeof date,"%b %e  %Y",&t);else strftime(date,sizeof date,"%b %e %H:%M",&t);char marker=' ';
#if defined(__linux__)
if(lgetxattr(full,"security.selinux",NULL,0)>0)marker='.';
#endif
printf("%s%c %lu %s %s %*lld %s %s",mode,marker,(unsigned long)st->st_nlink,owner,group,sw,(long long)st->st_size,date,name);if(S_ISLNK(st->st_mode)){char b[PATH_MAX+1];ssize_t n=readlink(full,b,PATH_MAX);if(n>=0){b[n]=0;printf(" -> %s",b);}}putchar('\n');}
static inline int zov_ls_list(const char*utility,const char*path,int all,int almost,int longfmt,int one,int columns,int dirself,int classify){struct stat root;if(lstat(path,&root)<0){fprintf(stderr,"%s: cannot access '%s': %s\n",utility,path,strerror(errno));return 2;}if(dirself||!S_ISDIR(root.st_mode)){if(longfmt)zov_ls_long(path,&root,path,zov_ls_digits((long long)root.st_size));else{fputs(path,stdout);if(classify){if(S_ISDIR(root.st_mode))putchar('/');else if(S_ISLNK(root.st_mode))putchar('@');else if(root.st_mode&(S_IXUSR|S_IXGRP|S_IXOTH))putchar('*');}putchar('\n');}return 0;}DIR*d=opendir(path);if(!d){fprintf(stderr,"%s: cannot open directory '%s': %s\n",utility,path,strerror(errno));return 2;}size_t n=0,cap=32;zov_lsentry*e=(zov_lsentry*)calloc(cap,sizeof(*e));if(!e){closedir(d);return 2;}struct dirent*de;long total=0;while((de=readdir(d))){if(!all&&!almost&&de->d_name[0]=='.')continue;if(almost&&(!strcmp(de->d_name,".")||!strcmp(de->d_name,"..")))continue;if(n==cap){cap*=2;zov_lsentry*p=(zov_lsentry*)realloc(e,cap*sizeof(*e));if(!p){closedir(d);return 2;}e=p;}e[n].name=zov_lsdup(de->d_name);char*full=zov_lspath(path,de->d_name);if(full&&lstat(full,&e[n].st)==0){e[n].valid=1;total+=(long)((e[n].st.st_blocks+1)/2);}free(full);n++;}closedir(d);if(zov_ls_sort_mode!=3)qsort(e,n,sizeof(*e),zov_lscmp);int sw=1;for(size_t i=0;i<n;i++){int d=zov_ls_digits((long long)e[i].st.st_size);if(d>sw)sw=d;}if(longfmt)printf("total %ld\n",total);if(columns&&!longfmt){size_t width=0;for(size_t i=0;i<n;i++){size_t z=strlen(e[i].name)+(classify&&e[i].valid&&(S_ISDIR(e[i].st.st_mode)||e[i].st.st_mode&S_IXUSR)?1:0);if(z>width)width=z;}size_t cols=width?82/(width+2):1;if(cols<1)cols=1;size_t rows=(n+cols-1)/cols;size_t*cw=(size_t*)calloc(cols,sizeof(size_t));for(size_t c=0;c<cols;c++)for(size_t r=0;r<rows;r++){size_t ix=c*rows+r;if(ix<n){size_t z=strlen(e[ix].name)+(classify&&e[ix].valid&&(S_ISDIR(e[ix].st.st_mode)||e[ix].st.st_mode&S_IXUSR)?1:0);if(z>cw[c])cw[c]=z;}}for(size_t r=0;r<rows;r++){for(size_t c=0;c<cols;c++){size_t ix=c*rows+r;if(ix>=n)continue;size_t z=strlen(e[ix].name);fputs(e[ix].name,stdout);if(classify&&e[ix].valid&&(S_ISDIR(e[ix].st.st_mode)||e[ix].st.st_mode&S_IXUSR)){putchar(S_ISDIR(e[ix].st.st_mode)?'/':'*');z++;}if(c+1<cols&&ix+rows<n){if(z%8==7)putchar('\t');else{size_t pad=cw[c]+2-z;while(pad--)putchar(' ');}}}putchar('\n');}free(cw);}else for(size_t i=0;i<n;i++){if(longfmt&&e[i].valid){char*full=zov_lspath(path,e[i].name);zov_ls_long(e[i].name,&e[i].st,full?full:e[i].name,sw);free(full);}else{fputs(e[i].name,stdout);if(classify&&e[i].valid){if(S_ISDIR(e[i].st.st_mode))putchar('/');else if(S_ISLNK(e[i].st.st_mode))putchar('@');else if(e[i].st.st_mode&(S_IXUSR|S_IXGRP|S_IXOTH))putchar('*');}putchar('\n');}}for(size_t i=0;i<n;i++)free(e[i].name);free(e);(void)one;return 0;}
static inline int zov_ls_run(const char*utility,int argc,char**argv){zov_ls_sort_mode=0;zov_ls_reverse=0;int all=0,almost=0,longfmt=!strcmp(utility,"vdir"),one=0,columns=!strcmp(utility,"dir"),dirself=0,classify=0,end=0,nf=0,status=0;const char**paths=(const char**)malloc((size_t)(argc+1)*sizeof(char*));if(!paths)return 2;for(int i=0;i<argc;i++){const char*a=argv[i];if(!end&&!strcmp(a,"--")){end=1;continue;}if(!end&&!strcmp(a,"--reverse")){zov_ls_reverse=1;continue;}if(!end&&!strcmp(a,"--sort=size")){zov_ls_sort_mode=1;continue;}if(!end&&!strcmp(a,"--sort=time")){zov_ls_sort_mode=2;continue;}if(!end&&!strcmp(a,"--sort=none")){zov_ls_sort_mode=3;continue;}if(!end&&(!strcmp(a,"--help")||!strcmp(a,"--version"))){if(!strcmp(a,"--version")){printf("%s (zovutils) 0.10.17\n",utility);free(paths);return 0;}printf("Usage: %s [OPTION]... [FILE]...\nList information about the FILEs (the current directory by default).\n  -a, --all             do not ignore entries starting with .\n  -A, --almost-all      do not list implied . and ..\n  -d, --directory       list directories themselves\n  -l                    use a long listing format\n  -1                    list one file per line\n  -C                    list entries by columns\n  -F, --classify        append indicator characters to entries\n      --help            display this help and exit\n      --version         output version information and exit\n",utility);free(paths);return 0;}if(!end&&a[0]=='-'&&a[1]){if(a[1]=='-'&&strcmp(a,"--all")&&strcmp(a,"--almost-all")&&strcmp(a,"--directory")&&strcmp(a,"--classify")&&strncmp(a,"--sort=",7)){fprintf(stderr,"%s: unrecognized option '%s'\nTry '%s --help' for more information.\n",utility,a,utility);free(paths);return 2;}if(!strcmp(a,"--all")){all=1;continue;}if(!strcmp(a,"--almost-all")){almost=1;continue;}if(!strcmp(a,"--directory")){dirself=1;continue;}if(!strcmp(a,"--classify")){classify=1;continue;}for(size_t j=1;a[j];j++){if(a[j]=='a')all=1;else if(a[j]=='A')almost=1;else if(a[j]=='l')longfmt=1;else if(a[j]=='1'){one=1;columns=0;longfmt=0;}else if(a[j]=='C'){columns=1;one=0;longfmt=0;}else if(a[j]=='d')dirself=1;else if(a[j]=='F')classify=1;else if(a[j]=='r')zov_ls_reverse=1;else if(a[j]=='S')zov_ls_sort_mode=1;else if(a[j]=='t')zov_ls_sort_mode=2;else if(a[j]=='U')zov_ls_sort_mode=3;else{fprintf(stderr,"%s: invalid option -- '%c'\nTry '%s --help' for more information.\n",utility,a[j],utility);free(paths);return 2;}}continue;}paths[nf++]=a;}if(!nf)paths[nf++]=".";if(longfmt)columns=0;for(int i=0;i<nf;i++){struct stat st;if(lstat(paths[i],&st)<0){fprintf(stderr,"%s: cannot access '%s': %s\n",utility,paths[i],strerror(errno));status=2;continue;}if(nf>1&&S_ISDIR(st.st_mode)&&!dirself){printf("%s:\n",paths[i]);}int r=zov_ls_list(utility,paths[i],all,almost,longfmt,one,columns,dirself,classify);if(r>status)status=r;if(i+1<nf)putchar('\n');}free(paths);return status;}
#endif
